import{_ as t,o,c as a,a3 as d}from"./chunks/framework.cNy3aYYk.js";const u=JSON.parse('{"title":"Help Desk real-time board sync (1.12.0) — Production Readiness Audit","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Help Desk real-time board sync (1.12.0) — Production Readiness Audit | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/help-desk-realtime-board-sync-1-12-0-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Help Desk real-time board sync (1.12.0) — Production Readiness Audit | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/help-desk-realtime-board-sync-1-12-0-production-readiness"}]]},"headers":[],"relativePath":"deployment/help-desk-realtime-board-sync-1-12-0-production-readiness.md","filePath":"deployment/help-desk-realtime-board-sync-1-12-0-production-readiness.md","lastUpdated":1791302999000}'),s={name:"deployment/help-desk-realtime-board-sync-1-12-0-production-readiness.md"};function n(r,e,i,c,l,p){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="help-desk-real-time-board-sync-1-12-0-—-production-readiness-audit" tabindex="-1">Help Desk real-time board sync (1.12.0) — Production Readiness Audit <a class="header-anchor" href="#help-desk-real-time-board-sync-1-12-0-—-production-readiness-audit" aria-label="Permalink to &quot;Help Desk real-time board sync (1.12.0) — Production Readiness Audit&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>2026-10-05</td></tr><tr><td><strong>Status</strong></td><td><strong>Go for production</strong></td></tr><tr><td><strong>Scope</strong></td><td>Private board channel <code>tenant.{id}.help-desk.board</code> + <code>HelpDeskTicketCreated</code>/<code>HelpDeskTicketUpdated</code>/<code>HelpDeskTicketStatusChanged</code>/<code>HelpDeskTicketAssigned</code>/<code>HelpDeskTicketDeleted</code> broadcasts; SPA debounce-invalidate hook; catalog <strong>help-desk 1.11.0 → 1.12.0</strong></td></tr><tr><td><strong>Companion</strong></td><td><a href="/developer-guide/help-desk">Help Desk developer guide</a> · <a href="/user-guide/help-desk-overview">Help Desk overview</a> · <a href="/deployment/tasks-realtime-board-sync-1-8-0-production-readiness">Tasks 1.8.0 readiness</a> (pattern source) · <a href="/changelog/">CHANGELOG</a></td></tr></tbody></table><hr><h2 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive summary&quot;">​</a></h2><p>The Help Desk status Kanban now stays in sync across open tabs/users without a manual refresh. Backend fires five <code>ShouldBroadcastNow</code> events off the existing <code>HelpDeskEventSubscriber</code> domain-event handlers onto a new private Reverb channel; the SPA joins that channel only while the board view is mounted and debounces invalidation of the board + stats queries so a burst of changes collapses into one refetch. The design deliberately mirrors the <strong>Tasks 1.8.0 / Leads 1.8.0 / Live Chat inbox invalidate pattern</strong> (refetch-on-signal) and explicitly avoids the <strong>Team Chat message-patching pattern</strong> (no per-card payload merging). Board columns are <code>HelpDeskStatusEnum</code> values (<code>status</code> / <code>previous_status</code>), not pipeline stages. Status broadcasts fire from the existing <code>HelpDeskTicketStatusChanged</code> domain event (Help Desk already had a dedicated status event, unlike Tasks which derives status-changed from update diffs).</p><p><strong>Go / No-Go:</strong> <strong>Go</strong>.</p><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th></tr></thead><tbody><tr><td>Platform freeze (no parallel realtime architecture; reuses <code>window.Echo</code>)</td><td><strong>Pass</strong></td></tr><tr><td>Channel auth: same tenant + <code>help-desk.view</code> (mirrors <code>TaskBoardChannel</code>)</td><td><strong>Pass</strong></td></tr><tr><td>Cross-tenant isolation</td><td><strong>Pass</strong> — different <code>tenantId</code> on the channel name is rejected by <code>HelpDeskBoardChannel::join</code></td></tr><tr><td>Broadcasts fire on create / update / status change / close / assign / unassign / delete</td><td><strong>Pass</strong></td></tr><tr><td>SPA payload contract (<code>broadcastWith</code>)</td><td><strong>Pass</strong> — <code>action</code>, <code>ticket_id</code>, <code>status</code>, <code>previous_status</code>, <code>assigned_to</code></td></tr><tr><td>Subject-only update does not emit <code>HelpDeskTicketStatusChanged</code></td><td><strong>Pass</strong></td></tr><tr><td><code>assigned_to</code> present on assigned payload (including unassign → <code>null</code>)</td><td><strong>Pass</strong></td></tr><tr><td>Broadcast failures never break ticket writes (<code>SafeRealtimeBroadcast</code>)</td><td><strong>Pass</strong></td></tr><tr><td>Domain events stay separate from broadcast classes</td><td><strong>Pass</strong> — new <code>App\\Events\\HelpDesk\\*Broadcast</code> namespace; existing <code>App\\Events\\HelpDeskTicket*</code> untouched</td></tr><tr><td>Catalog migrate-only <strong>1.12.0</strong> + CatalogSeeder companion</td><td><strong>Pass</strong></td></tr><tr><td>Playwright</td><td><strong>Pass</strong> — <code>npm run test:e2e:help-desk</code> (tenant): complaint-dialog + full human workflow (validation, categories, CRUD, status, notes, trash, Board/List) + KB links — <strong>3 passed</strong> (one login session per spec)</td></tr><tr><td>Pest coverage</td><td><strong>Pass</strong> — <code>HelpDeskRealtimeBoardTest</code> (8) + <code>HelpDeskModuleVersion1120BumpTest</code> (2) = <strong>10 passed</strong>; companion <code>AutomationEngineSupportTest</code> catalog snapshot <strong>1.12.0</strong></td></tr><tr><td>Security: cross-tenant isolation</td><td><strong>Pass</strong></td></tr><tr><td>Security: assignee-scoped board metadata (tenant-wide channel)</td><td><strong>Accepted</strong> — identical to Tasks 1.8.0; payload is id-only and SPA ignores content (API refetch remains assignee-scoped)</td></tr></tbody></table><h2 id="findings" tabindex="-1">Findings <a class="header-anchor" href="#findings" aria-label="Permalink to &quot;Findings&quot;">​</a></h2><h3 id="closed-audit-remediations" tabindex="-1">Closed (audit remediations) <a class="header-anchor" href="#closed-audit-remediations" aria-label="Permalink to &quot;Closed (audit remediations)&quot;">​</a></h3><p>None at first pass — implementation copied the Tasks 1.8.0 remediations (payload contract, unassign <code>null</code>, close as status broadcast, subject-only does not emit status_changed, <code>SafeRealtimeBroadcast</code>).</p><h3 id="accepted-intentional-ops-—-not-defects" tabindex="-1">Accepted (intentional / ops — not defects) <a class="header-anchor" href="#accepted-intentional-ops-—-not-defects" aria-label="Permalink to &quot;Accepted (intentional / ops — not defects)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>Severity</th><th>Notes</th></tr></thead><tbody><tr><td>R1</td><td>Info</td><td>Restore / force-delete do not emit a distinct restore event; force-delete still fires <code>HelpDeskTicketDeleted</code> (domain <code>force</code> flag). Restore stays off the board channel — same as Tasks 1.8.0</td></tr><tr><td>R2</td><td>Info</td><td>Notes, SLA, and mailbox ingest stay off the board channel except when they already fire ticket create/update/status domain events</td></tr><tr><td>R3</td><td>Ops</td><td>No Reverb in CI; live two-session smoke remains a staging checklist item</td></tr><tr><td>R4</td><td>Info</td><td>No Playwright realtime spec — same as Tasks / Leads / Live Chat. Existing one-session Help Desk Playwright still covers validation, CRUD, status, notes, trash, and Board/List toggle</td></tr><tr><td>R5</td><td>Info</td><td>Mobile Help Desk board realtime is out of scope (web Kanban only)</td></tr><tr><td>R6</td><td>Info</td><td>Channel join is tenant + <code>help-desk.view</code> (not per-assignee). Payload is id-only; HTTP refetch stays assignee-scoped</td></tr></tbody></table><h2 id="what-shipped" tabindex="-1">What shipped <a class="header-anchor" href="#what-shipped" aria-label="Permalink to &quot;What shipped&quot;">​</a></h2><h3 id="backend" tabindex="-1">Backend <a class="header-anchor" href="#backend" aria-label="Permalink to &quot;Backend&quot;">​</a></h3><ul><li><code>app/Broadcasting/HelpDeskBoardChannel.php</code> — private channel auth, same shape as <code>TaskBoardChannel</code> (tenant match + <code>help-desk.view</code>).</li><li><code>routes/channels.php</code> — registers <code>tenant.{tenantId}.help-desk.board</code>.</li><li><code>app/Events/HelpDesk/HelpDeskBoardBroadcastPayload.php</code> — shared payload builder (<code>action</code>, <code>ticket_id</code>, <code>uuid</code>, <code>actor_id</code>, <code>status</code>, optional <code>previous_status</code> / <code>assigned_to</code>).</li><li><code>app/Events/HelpDesk/HelpDeskTicket{Created,Updated,StatusChanged,Assigned,Deleted}Broadcast.php</code> — <code>ShouldBroadcastNow</code>, each <code>broadcastAs()</code> matching the SPA&#39;s <code>.HelpDeskTicketXxx</code> listener name.</li><li><code>app/Listeners/HelpDeskEventSubscriber.php</code> — create/update/assign/delete/status handlers fire the matching broadcast via <code>SafeRealtimeBroadcast::dispatch</code>.</li><li>Catalog: <code>database/migrations/2026_10_05_023800_bump_help_desk_module_to_1_12_0.php</code> (migrate-only, reversible) + <code>CatalogSeeder</code> <code>help-desk</code> version <strong>1.12.0</strong>.</li></ul><h3 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h3><ul><li><code>src/hooks/use-help-desk-board-realtime.ts</code> — subscribes via shared <code>window.Echo</code>; listens for all five events; debounces (~200ms) invalidate of <code>QUERY_KEYS.helpDeskBoard</code> + <code>QUERY_KEYS.helpDeskStats</code>.</li><li><code>src/pages/help-desk/help-desk-page.tsx</code> — calls the hook with <code>enabled: viewMode === &#39;board&#39;</code>.</li><li><code>src/types/api.ts</code> — <code>HelpDeskBoardRealtimePayload</code> type.</li></ul><h3 id="docs" tabindex="-1">Docs <a class="header-anchor" href="#docs" aria-label="Permalink to &quot;Docs&quot;">​</a></h3><ul><li>Help Desk user/developer/API/deployment/upgrade/roadmap guides updated; this readiness doc; CHANGELOG entry.</li></ul><h2 id="operator-checklist" tabindex="-1">Operator checklist <a class="header-anchor" href="#operator-checklist" aria-label="Permalink to &quot;Operator checklist&quot;">​</a></h2><ol><li><code>php artisan migrate --force</code> (catalog bump only — <strong>do not</strong> <code>db:seed</code>)</li><li>Deploy Frontend SPA with the Help Desk board hook</li><li>Confirm Reverb is running; <code>php artisan reverb:restart</code> if already up</li><li>Staging: two sessions on Help Desk <strong>Board</strong> — create, status drag, assign, delete; second session refetches without reload</li></ol><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><p><code>php artisan migrate:rollback</code> on <code>2026_10_05_023800_bump_help_desk_module_to_1_12_0</code> restores catalog <strong>1.11.0</strong>. Redeploy previous SPA to stop joining the channel. Broadcast classes are additive; rolling back the catalog does not drop ticket data.</p>',23)])])}const g=t(s,[["render",n]]);export{u as __pageData,g as default};
